static void bg_push_persp(float fov, float n, float f, int w, int h)
{
    GLfloat m[4][4];
    GLfloat r = (fov / 2.0f) * ((float) V_PI / 180.0f);
    GLfloat s = fsinf(r);
    GLfloat c = fcosf(r) / (s > 0.0001f ? s : 0.0001f);
    GLfloat a = (GLfloat) w / (GLfloat) (h > 0 ? h : 1);

    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();

    memset(m, 0, sizeof (m));
    m[0][0] = c / a;
    m[1][1] = c;
    m[2][2] = -(f + n) / (f - n);
    m[2][3] = -1.0f;
    m[3][2] = -2.0f * n * f / (f - n);

    glMultMatrixf(&m[0][0]);

    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();
}

static GLuint back_load_texture(const char *name)
{
    GLuint tex = make_image_from_file(name, IF_MIPMAP);

    if (tex)
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
    else
        log_printf("Failed to load background image \"%s\"\n", name);

    return tex;
}

static void back_push(const char *name)
{
    if (name && *name && back_depth < BACK_STACK_MAX)
    {
        GLuint tex = back_load_texture(name);

        if (tex)
        {
            SAFECPY(back_stack[back_depth].name, name);
            back_stack[back_depth].tex = tex;
            back_depth++;
        }
    }
}

static void back_pop(void)
{
    if (back_depth > 0)
    {
        back_depth--;

        if (back_stack[back_depth].tex)
        {
            glDeleteTextures(1, &back_stack[back_depth].tex);
            back_stack[back_depth].tex = 0;
        }
    }
}

static void back_draw_sky(struct s_rend *r)
{
    if (back_depth > 0 && sky_state)
    {
        struct mtrl *mp = mtrl_get(sky_geom.base.mtrls ? sky_geom.base.mtrls[0] : -1);

        if (mp)
            mp->o = back_stack[back_depth - 1].tex;

        glDisable(GL_DEPTH_TEST);
        glDisable(GL_CULL_FACE);
        glDepthMask(GL_FALSE);

        glPushMatrix();
        {
            glScalef(-BACK_DIST, BACK_DIST, -BACK_DIST);
            sol_draw(&sky_geom.draw, r, 1, 1);
        }
        glPopMatrix();

        glDepthMask(GL_TRUE);
        glEnable(GL_CULL_FACE);
        glEnable(GL_DEPTH_TEST);
    }
}

