int bg_init(int w, int h)
{
    win_w = (w > 0) ? w : 800;
    win_h = (h > 0) ? h : 600;

    video.device_w = win_w;
    video.device_h = win_h;

    SDL_SetHint("SDL_EMSCRIPTEN_KEYBOARD_ELEMENT", "#none");
    SDL_SetHintWithPriority("SDL_EMSCRIPTEN_KEYBOARD_ELEMENT", "#none", SDL_HINT_OVERRIDE);

    if (SDL_Init(SDL_INIT_VIDEO) < 0)
    {
        log_printf("SDL_Init failed: %s\n", SDL_GetError());
        return 0;
    }

    SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER, 1);
    SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE, 16);

    window = SDL_CreateWindow("Neverball Background",
                              SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED,
                              win_w, win_h,
                              SDL_WINDOW_OPENGL | SDL_WINDOW_RESIZABLE);
    if (!window)
    {
        log_printf("SDL_CreateWindow failed: %s\n", SDL_GetError());
        return 0;
    }

    context = SDL_GL_CreateContext(window);
    if (!context)
    {
        log_printf("SDL_GL_CreateContext failed: %s\n", SDL_GetError());
        return 0;
    }

#ifdef __EMSCRIPTEN__
    extern void *emscripten_GetProcAddress(const char *name);
    set_getprocaddress(emscripten_GetProcAddress);
    initialize_gl4es();
#endif

    glext_init();

    glEnable(GL_NORMALIZE);
    glEnable(GL_CULL_FACE);
    glEnable(GL_DEPTH_TEST);
    glEnable(GL_TEXTURE_2D);
    glEnable(GL_BLEND);

    glPixelStorei(GL_PACK_ALIGNMENT, 1);
    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);

    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    glDepthFunc(GL_LEQUAL);

    fs_init(NULL);
    dir_make("/data");
    fs_add_path("/data");

    mtrl_init();

    return 1;
}

